INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"看得数写乘法算式（每个写2道）：36=（　）×（　）=（　）×（　）。","options":null}', '6×6=36；4×9=36', '答案不唯一：表内乘法中积为36的有 6×6、4×9、9×4，任写2道即可。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p025.png"]');
