INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"把10米长的木头锯成4段，每锯一次要2分钟，一共需要（　）分钟。","options":null}', '6', '锯成4段只需锯3次：3×2=6（分钟）。“10米”是干扰条件。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p025.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"二（1）班同学排成正方形的队伍参加表演。从前、后、左、右数，小明都是排第4，参加表演的共有（　）人。","options":null}', '49', '从前、后数小明都排第4 → 前后各有3人，每列 3+1+3=7 人；左右同理每行7人。共 7×7=49（人）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p026.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"张叔叔在一个正方形池塘的四周种树，每条边上都种了5棵树，张叔叔最少种了（　）棵树。","options":null}', '16', '求最少 → 四个角都种。每边5棵，角上的树被两条边共用：4×5-4=16（棵）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p026.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"爷爷买了一筐苹果，个数比20多、比30少，4个4个地数多2个，5个5个地数少3个，一共有（　）个苹果。","options":null}', '22', '20~30之间“4个4个数多2”的有22、26；“5个5个数少3”即多2个：22=4×5+2 ✓，26=5×5+1 ✗。所以是22个。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p026.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem":"积是27的算式是（　）。","options":["A.9+9+9", "B.20+7", "C.9×3"]}', 'C', '积是乘法运算的结果：C 9×3=27；A（9+9+9）与 B（20+7）求的是和。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p026.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 3, '{"stem":"如图，每两面旗间隔6米，从第1面旗到第6面旗间隔（　）。","options":["A.30米", "B.36米", "C.42米"]}', 'A', '第1面到第6面旗之间共有 6-1=5 个间隔：5×6=30（米）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p026.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用题', 3, '{"stem":"东东家一共养了8只兔子，每只兔子每天吃9根胡萝卜，8只兔子每天要吃多少根胡萝卜？","options":null}', '72根', '8×9=72（根）。答：8只兔子每天要吃72根胡萝卜。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p027.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用题', 3, '{"stem":"欢欢从一楼到二楼用了7秒，按照这样的速度，从一楼到九楼，一共需要多少秒？","options":null}', '56秒', '从一楼到九楼共走 9-1=8 层，每层7秒：8×7=56（秒）。答：一共需要56秒。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p028.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用题', 3, '{"stem":"庆祝“元旦”，同学们做了红、黄、绿、蓝四种颜色的花各9朵，还做了5朵紫色的花，一共做了多少朵花？","options":null}', '41朵', '四种花各9朵：4×9=36（朵），再加紫色5朵：36+5=41（朵）。答：一共做了41朵花。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p028.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"奇妙的“9”：2×9=18，1+8=9；3×9=27，2+7=9。根据你发现的规律，接着写出两组：4×9=（　），（　）+（　）=（　）；5×9=（　），（　）+（　）=（　）。","options":null}', '36，3+6=9；45，4+5=9', '规律：9与一位数相乘，积的十位与个位数字之和等于9。4×9=36 → 3+6=9；5×9=45 → 4+5=9。（卷面若已印出“4×9=36”，只需填 3+6=9 与 5×9=45、4+5=9。）', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p028.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 4, '{"stem":"一群猫和一群狗进行拔河比赛，虽然猫比狗多8只，但最终双方打成平手。如果2只猫与1只狗的力气相等，那么共有（　）只猫。","options":null}', '16', '设狗 x 只，则猫 x+8 只。2只猫的力气=1只狗，狗方总力气=2x 只猫的力气；平手：2x=x+8，解得 x=8，猫有 8+8=16（只）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p028.png"]');
